async function closeDrawer(name,{nativeTest=false}={}){await startCapture(name);await(await hideButton()).focus();await page.keyboard.press('Enter');await page.waitForFunction(()=>document.querySelector('.dashboard-shell')?.dataset.contentPhase==='closing');if(nativeTest){await pause(65);await nativeRegions(name+'-native',{moving:true,leak:true})};await stopCapture(name,{terminal:'closed'});assert.equal(await inner().evaluate(e=>!!e.closest('[inert]')),true);assert(await restore().count()>0)}
